package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.zip.ZipException;
import org.apache.commons.compress.utils.Lang;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Zip64ExtendedInformationExtraField_parseFromLocalFileData_TriageGen1Test {

    private static final int DWORD = 4;
    private static final int WORD = 2;

    @Test
    public void testParseFromLocalFileData_LengthZero() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[10];

        // Should return immediately without doing anything
        field.parseFromLocalFileData(buffer, 0, 0);

        assertNull(field.getSize());
        assertNull(field.getCompressedSize());
    }

    @Test(expected = ZipException.class)
    public void testParseFromLocalFileData_LengthTooShort() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[10];
        // length < 2 * DWORD (8)
        field.parseFromLocalFileData(buffer, 0, 7);
    }

    @Test
    public void testParseFromLocalFileData_MinimumRequiredFields() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[8];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putInt(100); // size
        bb.putInt(50);  // compressedSize

        field.parseFromLocalFileData(buffer, 0, 8);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        assertNull(field.getRelativeHeaderOffset());
        assertNull(field.getDiskStartNumber());
    }

    @Test
    public void testParseFromLocalFileData_WithRelativeHeaderOffset() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD (8) + 1 * DWORD (4) = 12
        byte[] buffer = new byte[12];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putInt(100); // size
        bb.putInt(50);  // compressedSize
        bb.putInt(200); // relativeHeaderOffset

        field.parseFromLocalFileData(buffer, 0, 12);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        assertEquals(200L, field.getRelativeHeaderOffset().longValue());
        assertNull(field.getDiskStartNumber());
    }

    @Test
    public void testParseFromLocalFileData_WithDiskStart() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD (8) + 1 * DWORD (4) + 1 * WORD (2) = 14
        byte[] buffer = new byte[14];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putInt(100); // size
        bb.putInt(50);  // compressedSize
        bb.putInt(200); // relativeHeaderOffset
        bb.putShort((short) 5); // diskStart

        field.parseFromLocalFileData(buffer, 0, 14);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        assertEquals(200L, field.getRelativeHeaderOffset().longValue());
        assertEquals(5L, field.getDiskStartNumber().longValue());
    }

    @Test
    public void testParseFromLocalFileData_WithOffset() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[20];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        int offset = 5;

        // Skip 5 bytes
        bb.position(offset);
        bb.putInt(100); // size
        bb.putInt(50);  // compressedSize
        bb.putInt(200); // relativeHeaderOffset
        bb.putShort((short) 5); // diskStart

        field.parseFromLocalFileData(buffer, offset, 14);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        assertEquals(200L, field.getRelativeHeaderOffset().longValue());
        assertEquals(5L, field.getDiskStartNumber().longValue());
    }

    @Test
    public void testParseFromLocalFileData_LargeLengthDoesNotAffectParsing() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[100];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putInt(100);
        bb.putInt(50);

        // length is 100, but we only provide 8 bytes of meaningful data
        // The logic uses 'remaining' based on length, so we must ensure buffer is large enough
        // to prevent IndexOutOfBounds if the logic tries to read more than provided in buffer
        // However, the method uses 'remaining' to decide whether to read, so it's safe.
        field.parseFromLocalFileData(buffer, 0, 100);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
    }
}
